create type public.plan as enum ('free','pro','ultra');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,display_name text,avatar_url text,plan public.plan not null default 'free',is_admin boolean not null default false,is_blocked boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,thumbnail_url text,project_data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_files(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,file_url text not null,file_type text not null,file_size bigint not null default 0,created_at timestamptz not null default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,revenuecat_app_user_id text not null,entitlement text not null,status text not null,current_period_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_settings(user_id uuid primary key references auth.users(id) on delete cascade,settings jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table public.exports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete set null,resolution text not null,fps int not null,quality text not null,file_url text,status text not null default 'queued',created_at timestamptz not null default now());
create table public.usage(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,feature text not null,usage_count int not null default 0,period text not null,created_at timestamptz not null default now());
create table public.admin_logs(id uuid primary key default gen_random_uuid(),admin_user_id uuid references auth.users(id),action text not null,target_user_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.project_files enable row level security; alter table public.subscriptions enable row level security; alter table public.user_settings enable row level security; alter table public.exports enable row level security; alter table public.usage enable row level security; alter table public.admin_logs enable row level security;
create policy own_profile on public.profiles for select using (auth.uid()=id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
create policy update_own_profile on public.profiles for update using (auth.uid()=id);
create policy own_projects on public.projects for all using (auth.uid()=user_id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
create policy own_files on public.project_files for all using (auth.uid()=user_id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
create policy own_subscriptions on public.subscriptions for select using (auth.uid()=user_id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
create policy own_settings on public.user_settings for all using (auth.uid()=user_id);
create policy own_exports on public.exports for all using (auth.uid()=user_id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
create policy own_usage on public.usage for select using (auth.uid()=user_id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
create policy admin_logs_admin on public.admin_logs for select using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin));
insert into storage.buckets(id,name,public) values ('avatars','avatars',false),('projects','projects',false),('media','media',false),('thumbnails','thumbnails',false),('exports','exports',false) on conflict do nothing;
